// Entire CLI plugin for OpenCode
// Auto-generated by `entire enable --agent opencode`
// Do not edit manually — changes will be overwritten on next install.
// Requires Bun runtime (used by OpenCode's plugin system for loading ESM plugins).
import type { Plugin } from "@opencode-ai/plugin"

/**
 * Spawns a child process that cleans up tracked sessions when the parent
 * process exits — including abrupt exits (SIGKILL, os.Exit) where no
 * "session.deleted" event fires.
 *
 * How it works:
 * 1. A child Node process is spawned with its stdin piped from the parent.
 * 2. The parent sends JSON-line messages to track/untrack session IDs.
 * 3. When the parent exits, the OS closes the pipe → the child gets stdin EOF.
 * 4. On EOF, the child calls `entire hooks opencode session-end` for each
 *    session that was tracked but never untracked.
 */
function spawnSessionCleanupWatcher(entireCmd: string) {
  // The script below runs in the child process. It reads JSON-line messages
  // from stdin and maintains a set of tracked session IDs. When stdin closes
  // (parent exited), it calls session-end for each remaining session.
  const script = `
    const { execFileSync } = require("child_process");
    const cmd = ${JSON.stringify(entireCmd)};
    const sessions = new Set();
    let buf = "";

    process.stdin.setEncoding("utf8");

    process.stdin.on("data", (chunk) => {
      buf += chunk;
      let i;
      while ((i = buf.indexOf("\\n")) !== -1) {
        const line = buf.slice(0, i);
        buf = buf.slice(i + 1);
        try {
          const msg = JSON.parse(line);
          if (msg.type === "track") sessions.add(msg.id);
          else if (msg.type === "untrack") sessions.delete(msg.id);
        } catch {}
      }
    });

    process.stdin.on("end", () => {
      for (const id of sessions) {
        try {
          execFileSync(cmd, ["hooks", "opencode", "session-end"], {
            input: JSON.stringify({ session_id: id }),
            timeout: 10000,
          });
        } catch {}
      }
    });
  `;

  let child: ReturnType<typeof Bun.spawn> | null = null;
  try {
    child = Bun.spawn(["node", "-e", script], {
      stdin: "pipe",
      stdout: "ignore",
      stderr: "ignore",
    });
  } catch {
    // node not available — watcher disabled, plugin still works normally
  }

  function send(type: string, sessionId: string) {
    if (!child) return;
    try {
      child.stdin.write(JSON.stringify({ type, id: sessionId }) + "\n");
      child.stdin.flush();
    } catch {
      // Child already exited — nothing to do
    }
  }

  return {
    track: (sessionId: string) => send("track", sessionId),
    untrack: (sessionId: string) => send("untrack", sessionId),
  };
}

